// Extract NotebookLM data from webhook
const notebookData = items[0].json;

return [{
  json: {
    notebook_id: notebookData.notebook_id,
    source_summary: notebookData.summary || '',
    key_points: notebookData.key_points || [],
    sources: notebookData.sources || [],
    content_requests: notebookData.content_requests || [],
    timestamp: new Date().toISOString()
  }
}];

// Run Fair Use compliance check
const sources = items[0].json.sources;
const contentRequests = items[0].json.content_requests;

const complianceCheck = {
  factor_1_transformation: 0,
  factor_2_nature: 0,
  factor_3_amount: 0,
  factor_4_market: 0,
  overall_score: 0,
  passed: false,
  warnings: []
};

// Factor 1: Check transformation plan
if (contentRequests[0]?.transformation_plan) {
  complianceCheck.factor_1_transformation = 85;
} else {
  complianceCheck.warnings.push('No transformation plan specified');
  complianceCheck.factor_1_transformation = 40;
}

// Factor 2: Nature of work (educational/factual content safer)
const educationalKeywords = ['tutorial', 'guide', 'how-to', 'review', 'analysis'];
const hasEducational = sources.some(s => 
  educationalKeywords.some(kw => s.title?.toLowerCase().includes(kw))
);
complianceCheck.factor_2_nature = hasEducational ? 80 : 60;

// Factor 3: Amount used (check source count)
if (sources.length >= 5) {
  complianceCheck.factor_3_amount = 90;  // Good synthesis
} else if (sources.length >= 3) {
  complianceCheck.factor_3_amount = 70;  // Moderate
} else {
  complianceCheck.warnings.push('Less than 3 sources - add more for better Fair Use');
  complianceCheck.factor_3_amount = 40;
}

// Factor 4: Market effect (check if different platform/purpose)
const differentPlatform = contentRequests[0]?.target_platform !== 'youtube';
complianceCheck.factor_4_market = differentPlatform ? 85 : 60;

// Calculate overall score
complianceCheck.overall_score = (
  complianceCheck.factor_1_transformation +
  complianceCheck.factor_2_nature +
  complianceCheck.factor_3_amount +
  complianceCheck.factor_4_market
) / 4;

complianceCheck.passed = complianceCheck.overall_score >= 70;

return [{
  json: {
    ...items[0].json,
    compliance_check: complianceCheck,
    status: complianceCheck.passed ? 'compliant' : 'needs_review'
  }
}];

// Generate compressed prompt for Claude
const summary = items[0].json.source_summary;
const keyPoints = items[0].json.key_points;
const sources = items[0].json.sources;
const request = items[0].json.content_requests[0];

// Compressed prompt (token-efficient)
const prompt = `Write ${request.word_count}-word ${request.format} on ${request.topic}.

Source Summary:
${summary.substring(0, 500)}  // Truncate for efficiency

Key Points:
${keyPoints.slice(0, 5).join('\n')}

Structure:
1. ${request.structure?.intro || 'Introduction with hook'}
2. ${request.structure?.main || '3-4 main points with examples'}
3. ${request.structure?.conclusion || 'Actionable conclusion'}

Tone: ${request.tone || 'Professional'}
Audience: ${request.audience || 'General'}

IMPORTANT: This is transformative content. Add:
- Original analysis and insights
- New frameworks/comparisons
- Expert commentary
- Different perspective from sources

[ATTRIBUTION_PLACEHOLDER]`;

return [{
  json: {
    ...items[0].json,
    compressed_prompt: prompt,
    estimated_tokens: Math.ceil(prompt.length / 4),
    status: 'ready_for_generation'
  }
}];

// Select optimal Claude model based on complexity
const request = items[0].json.content_requests[0];

let complexityScore = 0;

// Factors affecting complexity
if (request.word_count > 2000) complexityScore += 20;
if (request.requires_research) complexityScore += 25;
if (items[0].json.sources.length > 5) complexityScore += 20;
if (request.analysis_depth === 'deep') complexityScore += 30;

let selectedModel;
if (complexityScore < 30) {
  selectedModel = 'claude-haiku-4-5';  // $3/1M tokens
} else if (complexityScore < 70) {
  selectedModel = 'claude-sonnet-4-5-20250929';  // $30/1M tokens
} else {
  selectedModel = 'claude-opus-4';  // $60/1M tokens
}

return [{
  json: {
    ...items[0].json,
    selected_model: selectedModel,
    complexity_score: complexityScore,
    estimated_cost: this.estimateCost(selectedModel, items[0].json.estimated_tokens)
  }
}];

// Helper function
function estimateCost(model, tokens) {
  const pricing = {
    'claude-haiku-4-5': 3,
    'claude-sonnet-4-5-20250929': 30,
    'claude-opus-4': 60
  };
  return ((tokens / 1000000) * pricing[model]).toFixed(4);
}

// Extract generated content from Claude response
const response = items[0].json;
const generatedContent = response.content[0].text;

// Calculate actual cost
const inputTokens = response.usage.input_tokens;
const outputTokens = response.usage.output_tokens;
const model = items[0].json.selected_model;

const pricing = {
  'claude-haiku-4-5': { input: 1, output: 5 },
  'claude-sonnet-4-5-20250929': { input: 3, output: 15 },
  'claude-opus-4': { input: 15, output: 75 }
};

const cost = (
  (inputTokens / 1000000) * pricing[model].input +
  (outputTokens / 1000000) * pricing[model].output
);

return [{
  json: {
    ...items[0].json,
    generated_content: generatedContent,
    actual_cost: cost.toFixed(4),
    tokens_used: {
      input: inputTokens,
      output: outputTokens,
      total: inputTokens + outputTokens
    },
    status: 'generated'
  }
}];

// Add attribution automatically
const AttributionEngine = {
  generateAttribution(sources, platform) {
    let attribution = '\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━\n';
    attribution += '📚 SOURCES & ATTRIBUTION\n';
    attribution += '━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n';
    attribution += 'This content is based on analysis and synthesis of:\n\n';

    sources.forEach((source, index) => {
      attribution += `${index + 1}. "${source.title}"\n`;
      attribution += `   by ${source.creator}\n`;
      attribution += `   ${source.url}\n\n`;
    });

    attribution += 'This content adds:\n';
    attribution += '• Comprehensive analysis and synthesis\n';
    attribution += '• Expert insights and recommendations\n';
    attribution += '• Structured comparison framework\n';
    attribution += '• Additional context and research\n\n';
    attribution += 'This use constitutes Fair Use under 17 U.S.C. § 107.\n';

    return attribution;
  }
};

const content = items[0].json.generated_content;
const sources = items[0].json.sources;
const platform = items[0].json.content_requests[0]?.target_platform || 'blog';

// Replace attribution placeholder
const attribution = AttributionEngine.generateAttribution(sources, platform);
const finalContent = content.replace('[ATTRIBUTION_PLACEHOLDER]', attribution);

return [{
  json: {
    ...items[0].json,
    final_content: finalContent,
    attribution_added: true,
    status: 'attribution_complete'
  }
}];

// Log compliance failure
const failureRecord = {
  notebook_id: items[0].json.notebook_id,
  compliance_check: items[0].json.compliance_check,
  failed_at: new Date().toISOString(),
  action_required: 'Review transformation plan'
};

return [{
  json: failureRecord
}];
